                        + String.join(", ", cols.stream().map(SheetHistory::quote).toList()) + ")"
                        + (keyed ? " KEY (" + String.join(", ", t.key().stream().map(SheetHistory::quote).toList()) + ")" : "")
                        + " VALUES (" + String.join(", ", Collections.nCopies(cols.size(), "?")) + ")";
